package com.company.platform.commerce.infrastructure;
import com.company.platform.commerce.domain.events.CommerceEvent; import com.company.platform.shared.contracts.PlatformEvent; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.slf4j.MDC; import java.util.*;
@Component public class KafkaCommerceEventPublisher { private final KafkaTemplate<String,Object> kafka; public KafkaCommerceEventPublisher(KafkaTemplate<String,Object> kafka){this.kafka=kafka;} public void publish(CommerceEvent event){String topic=event.eventType().startsWith("Cart")?"commerce.cart.events":event.eventType().startsWith("Price")?"commerce.price.events":event.eventType().startsWith("Commercial")?"commerce.rules.events":"commerce.product.events";var auth=SecurityContextHolder.getContext().getAuthentication();String user=auth==null?"system":auth.getName();String correlation=Optional.ofNullable(MDC.get("correlationId")).orElseGet(()->UUID.randomUUID().toString());Map<String,Object> payload=Map.of("eventType",event.eventType(),"aggregateId",event.aggregateId().toString(),"data",event.payload());PlatformEvent<Map<String,Object>> envelope=new PlatformEvent<>(event.eventId().toString(),event.tenantId().toString(),user,correlation,event.occurredAt(),"commerce-service",payload);kafka.send(topic,event.aggregateId().toString(),envelope);}}
